package com.codearena.messaging; 
import org.springframework.amqp.core.*; 
import org.springframework.context.annotation.*;

@Configuration public class MessagingConfig { @Bean DirectExchange submissionExchange(){return new DirectExchange("submission.exchange",true,false);} @Bean FanoutExchange submissionDlx(){return new FanoutExchange("submission.dlx",true,false);} @Bean Queue submissionQueue(){return QueueBuilder.durable("submission.execute").deadLetterExchange("submission.dlx").ttl(30000).build();} @Bean Binding submissionBinding(){return BindingBuilder.bind(submissionQueue()).to(submissionExchange()).with("submission.created");} @Bean Queue submissionDlq(){return QueueBuilder.durable("submission.dead").build();} @Bean Binding deadBinding(){return BindingBuilder.bind(submissionDlq()).to(submissionDlx());} @Bean DirectExchange emailExchange(){return new DirectExchange("email.exchange",true,false);} @Bean Queue emailQueue(){return QueueBuilder.durable("email.send").deadLetterExchange("submission.dlx").build();} @Bean Binding emailBinding(){return BindingBuilder.bind(emailQueue()).to(emailExchange()).with("email.created");} @Bean DirectExchange notificationExchange(){return new DirectExchange("notification.exchange",true,false);} @Bean Queue notificationQueue(){return QueueBuilder.durable("notification.deliver").deadLetterExchange("submission.dlx").build();} @Bean Binding notificationBinding(){return BindingBuilder.bind(notificationQueue()).to(notificationExchange()).with("notification.created");} @Bean DirectExchange analyticsExchange(){return new DirectExchange("analytics.exchange",true,false);} @Bean Queue analyticsQueue(){return QueueBuilder.durable("analytics.aggregate").deadLetterExchange("submission.dlx").build();} @Bean Binding analyticsBinding(){return BindingBuilder.bind(analyticsQueue()).to(analyticsExchange()).with("analytics.created");} }
